import {chromosomeIDs,nucleusInventory,stageIndex} from './division-models.js?v=20261023-physicscomplete01';
let serial=0;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function rod(id,x,y,{copied=false,label=true,small=false}={}){const long=id.startsWith('A'),h=(long?58:38)*(small?.7:1),colour=id.endsWith('1')?'#edab94':'#bed2d3';return '<g transform="translate('+x+' '+y+')"><path d="M-5 '+(-h/2)+' Q5 0 -5 '+h/2+'" fill="none" stroke="'+colour+'" stroke-width="8" stroke-linecap="round"/>'+(copied?'<path d="M7 '+(-h/2)+' Q-3 0 7 '+h/2+'" fill="none" stroke="'+colour+'" stroke-width="8" stroke-linecap="round"/>':'')+'<path d="M-10 -9 H2 M-10 9 H2" stroke="#182e44" stroke-width="2"/>'+(label?'<text x="0" y="'+(h/2+18)+'" fill="#e5edf0" font-size="16" text-anchor="middle">'+id+'</text>':'')+'</g>';}
export function chromosomeFigure({level='nucleus',region='A',labelled=false,copied=false,assessment=false}={}){level=['nucleus','chromosome','dna','gene'].includes(level)?level:'nucleus';region=['A','B','C'].includes(region)?region:'A';const id='genome'+(++serial);let art='';
 if(level==='nucleus'){art='<ellipse cx="210" cy="164" rx="160" ry="126" fill="url(#'+id+')" stroke="#acc2ca" stroke-width="3"/><ellipse cx="210" cy="155" rx="115" ry="94" fill="#6c607a" fill-opacity=".6" stroke="#c9bbc6" stroke-width="2"/>'+chromosomeIDs.map((c,i)=>rod(c,132+i*52,145)).join('')+'<path d="M115 222 H185 M235 222 H305" stroke="#b7c8d6" stroke-width="2"/><text x="150" y="242" text-anchor="middle" fill="#e5edf0" font-size="12">Pair A</text><text x="270" y="242" text-anchor="middle" fill="#e5edf0" font-size="12">Pair B</text>';}
 if(level==='chromosome'){art='<path d="M195 56 Q230 155 195 267" stroke="#e2ad9d" stroke-width="31" stroke-linecap="round" fill="none"/>'+['A','B','C'].map((v,i)=>'<path d="M178 '+(98+i*58)+' H222" stroke="'+(v===region?'#f48b78':'#182e44')+'" stroke-width="'+(v===region?13:6)+'"/><text x="252" y="'+(104+i*58)+'" fill="#e5edf0" font-size="15">Region '+v+'</text>').join('');}
 if(level==='chromosome'&&copied){art='<path d="M165 55 Q210 165 255 272 M255 55 Q210 165 165 272" fill="none" stroke="#e2ad9d" stroke-width="19" stroke-linecap="round"/><circle cx="210" cy="164" r="13" fill="#b77e89"/>';}
 if(level==='dna'||level==='gene'){const chosen={A:2,B:6,C:10}[region];const start=level==='gene'?chosen-1:0,length=level==='gene'?6:15;const points=sign=>Array.from({length},(_,j)=>{const i=j+start;return (210+sign*65*Math.sin(i*.7))+','+(34+j*(level==='gene'?44:17));}).join(' ');art='<polyline points="'+points(1)+'" fill="none" stroke="#d8b4a6" stroke-width="5"/><polyline points="'+points(-1)+'" fill="none" stroke="#c3d9d6" stroke-width="5"/>'+Array.from({length},(_,j)=>{const i=j+start,y=34+j*(level==='gene'?44:17),x1=210+65*Math.sin(i*.7),x2=210-65*Math.sin(i*.7),active=level==='gene'||Math.abs(i-chosen)<=1;return '<path d="M'+x1+' '+y+' H'+x2+'" stroke="'+(active?'#f48b78':'#a7bcc9')+'" stroke-width="'+(active?6:3)+'"/><circle cx="'+x1+'" cy="'+y+'" r="5" fill="#d8b4a6"/><circle cx="'+x2+'" cy="'+y+'" r="5" fill="#c3d9d6"/>';}).join('')+'<text x="210" y="316" text-anchor="middle" fill="#e5edf0" font-size="14">'+(level==='gene'?'Highlighted section of DNA':'Illustrative DNA · region '+region+' highlighted')+'</text>';}
 return '<svg class="bio-cell-art" viewBox="0 0 420 340" role="img" aria-label="'+(labelled?escape(level+' model'):'Genetic material schematic')+'"><title>Genetic material schematic</title><desc>'+ (copied?'An X-shaped structure with two joined arms.':'Symbolic genetic material. Rods in the nucleus view represent four unreplicated chromosomes labelled A1,A2,B1,B2.') +' Sizes, colours, gene positions and chromosome count are illustrative.</desc><defs><radialGradient id="'+id+'"><stop stop-color="#8eacb9"/><stop offset="1" stop-color="#45647e"/></radialGradient></defs>'+art+'</svg>';}
export function cycleFigure({stage=0,assignments=null,grown=false,assessment=false}={}){const n=stageIndex(stage),id='cycle'+(++serial);let art='';if(n<4)art='<ellipse cx="210" cy="160" rx="'+(n===0&&!grown?145:180)+'" ry="125" fill="url(#'+id+')" stroke="#acc2ca" stroke-width="3"/>';else art=[105,315].map(x=>'<ellipse cx="'+x+'" cy="160" rx="94" ry="118" fill="url(#'+id+')" stroke="#acc2ca" stroke-width="3"/>').join('');
 if(n<2){art+='<ellipse cx="210" cy="145" rx="103" ry="83" fill="#77647e" fill-opacity=".65" stroke="#d1bfce" stroke-width="2"/>'+chromosomeIDs.map((c,i)=>rod(c,137+i*50,136,{copied:n===1})).join('');if(n===0||n===1)art+=Array.from({length:n===0&&!grown?3:6},(_,i)=>'<ellipse cx="'+(n===0&&!grown?160+i*50:110+i*40)+'" cy="245" rx="12" ry="6" fill="#d9b587"/>').join('');}
 else{const sides=['L','R'];art+=sides.map((side,j)=>{const x=n===4?(j?315:105):(j?303:117),inventory=assignments?nucleusInventory(assignments,side):chromosomeIDs;return '<ellipse cx="'+x+'" cy="154" rx="76" ry="76" fill="#77647e" fill-opacity=".65" stroke="#d1bfce" stroke-width="2"/>'+inventory.map((c,i)=>rod(c,x-55+(i%4)*37,130+Math.floor(i/4)*57,{small:true})).join('')+'<text x="'+x+'" y="270" fill="#e5edf0" text-anchor="middle" font-size="13">'+(n===4?'Cell ':'Nucleus ')+(j+1)+'</text>';}).join('');if(n===3)art+='<path d="M210 34 Q154 160 210 286 M210 34 Q266 160 210 286" fill="none" stroke="#f48b78" stroke-width="4"/>';}
 return '<svg class="bio-cell-art" viewBox="0 0 420 340" role="img" aria-label="Cell-cycle snapshot '+n+'"><title>Cell-cycle schematic</title><desc>'+ (assessment?(n===4?'Two outlined cells each contain A1,A2,B1,B2.':n===2?'One cell outline contains two outlined nuclear regions, each containing A1,A2,B1,B2.':'Schematic cell and labelled genetic material.'):'Five teaching snapshots illustrate three overall stages, not five named mitosis phases. Four original chromosomes are shown.') +' No species chromosome count, scale or timing is implied.</desc><defs><radialGradient id="'+id+'"><stop stop-color="#93acb9"/><stop offset="1" stop-color="#49677f"/></radialGradient></defs>'+art+'<text x="210" y="324" text-anchor="middle" fill="#e5edf0" font-size="13">'+(assessment?'Schematic evidence':(['Preparation · before DNA copying','4 duplicated chromosomes · 8 DNA copies','DNA copies allocated to nuclei','Cytoplasm and membrane divide','Two daughter cells · one complete set each'][n]))+'</text></svg>';}
